#!/usr/bin/env python3
# Generated by Cursor
# Edited by Cursor (multi-correction support: corrections list, stats over pairs)
"""
Compute keyboard distance and Levenshtein distance for typo candidates.

Keyboard distance: min steps (insert=1, delete=1, adjacent-key substitute=1,
swap adjacent chars=1; non-adjacent substitute = shortest path on QWERTY).
"""

import argparse
import json
import sys
from collections import deque
from collections.abc import Iterator
from pathlib import Path

# QWERTY rows (US layout)
QWERTY = [
    "qwertyuiop",
    "asdfghjkl",
    "zxcvbnm",
]


def _build_keyboard_graph() -> tuple[dict[str, set[str]], dict[str, dict[str, int]]]:
    """Adjacency sets and pairwise shortest path lengths (BFS)."""
    # Horizontal + vertical neighbors (no diagonal for cleaner steps)
    pos: dict[str, tuple[int, int]] = {}
    for r, row in enumerate(QWERTY):
        for c, ch in enumerate(row):
            pos[ch] = (r, c)
    adj: dict[str, set[str]] = {}
    for ch, (r, c) in pos.items():
        adj[ch] = set()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            r2, c2 = r + dr, c + dc
            if 0 <= r2 < len(QWERTY) and 0 <= c2 < len(QWERTY[r2]):
                adj[ch].add(QWERTY[r2][c2])
    # Pairwise shortest path (only for a-z; case-fold)
    dist: dict[str, dict[str, int]] = {}
    for ch in pos:
        dist[ch] = {ch: 0}
        q: deque[tuple[str, int]] = deque([(ch, 0)])
        while q:
            u, d = q.popleft()
            for v in adj[u]:
                if v not in dist[ch]:
                    dist[ch][v] = d + 1
                    q.append((v, d + 1))
    return adj, dist


_ADJ, _KEY_DIST = _build_keyboard_graph()


def _key_sub_cost(a: str, b: str) -> int:
    """Cost to substitute a with b on keyboard (0 if same, 1 if adjacent, else path length)."""
    a, b = a.lower(), b.lower()
    if a == b:
        return 0
    if a not in _ADJ or b not in _ADJ:
        return 1  # non-letter: treat as 1
    return _KEY_DIST[a].get(b, 5)  # cap if unreachable


def keyboard_distance(typo: str, correction: str) -> int:
    """Min keyboard steps to transform typo into correction."""
    s, t = typo, correction
    n, m = len(s), len(t)
    # dp[i][j] = min steps for s[:i] -> t[:j]
    dp: list[list[int]] = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][0] = i
    for j in range(m + 1):
        dp[0][j] = j
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            dp[i][j] = min(
                dp[i - 1][j] + 1,
                dp[i][j - 1] + 1,
                dp[i - 1][j - 1] + _key_sub_cost(s[i - 1], t[j - 1]),
            )
            # Swap adjacent: s[i-2],s[i-1] -> t[j-1],t[j-2]
            if i >= 2 and j >= 2 and s[i - 2] == t[j - 1] and s[i - 1] == t[j - 2]:
                dp[i][j] = min(dp[i][j], dp[i - 2][j - 2] + 1)
    return dp[n][m]


def levenshtein_distance(typo: str, correction: str) -> int:
    """Return standard edit distance (insert, delete, substitute = 1 each)."""
    s, t = typo, correction
    n, m = len(s), len(t)
    dp: list[list[int]] = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][0] = i
    for j in range(m + 1):
        dp[0][j] = j
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            sub = 0 if s[i - 1] == t[j - 1] else 1
            dp[i][j] = min(
                dp[i - 1][j] + 1,
                dp[i][j - 1] + 1,
                dp[i - 1][j - 1] + sub,
            )
    return dp[n][m]


def main() -> None:
    """Load candidates, compute/fill distances, print stats and write back."""
    parser = argparse.ArgumentParser(
        description="Compute keyboard and Levenshtein distances for typo candidates."
    )
    parser.add_argument(
        "-i",
        "--input",
        type=Path,
        default=Path("data/transcription_typo_candidates.json"),
        help="Input candidate JSON (unified or legacy)",
    )
    parser.add_argument(
        "-o",
        "--output",
        type=Path,
        default=None,
        help="Output JSON (default: overwrite input)",
    )
    args = parser.parse_args()
    path = args.input
    out_path = args.output or path
    with path.open() as f:
        data = json.load(f)

    candidates = data["candidates"]
    # Unified: span; legacy: typo. Same for corrections list vs single correction.
    for c in candidates:
        span = c.get("span") or c.get("typo")
        if "corrections" in c:
            for corr_obj in c["corrections"]:
                if "keyboard_dist" not in corr_obj:
                    corr_obj["keyboard_dist"] = keyboard_distance(
                        span, corr_obj["text"]
                    )
                if "levenshtein_dist" not in corr_obj:
                    corr_obj["levenshtein_dist"] = levenshtein_distance(
                        span, corr_obj["text"]
                    )
        else:
            # Legacy single correction
            c["keyboard_dist"] = keyboard_distance(span, c["correction"])
            c["levenshtein_dist"] = levenshtein_distance(span, c["correction"])

    # Flatten to (span, correction, k, lev) for stats
    def pairs() -> Iterator[tuple[str, str, int, int]]:
        for c in candidates:
            span = c.get("span") or c.get("typo")
            if "corrections" in c:
                for corr in c["corrections"]:
                    yield (
                        span,
                        corr["text"],
                        corr["keyboard_dist"],
                        corr["levenshtein_dist"],
                    )
            else:
                yield span, c["correction"], c["keyboard_dist"], c["levenshtein_dist"]

    pairs_list = list(pairs())
    kd = [p[2] for p in pairs_list]
    ld = [p[3] for p in pairs_list]
    n = len(pairs_list)

    def bins_hist(vals: list[int], bins: list[tuple[int, int]]) -> list[int]:
        return [sum(1 for v in vals if lo <= v <= hi) for lo, hi in bins]

    kbins = [(1, 1), (2, 2), (3, 3), (4, 5), (6, 10), (11, 100)]
    lbins = [(1, 1), (2, 2), (3, 3), (4, 5), (6, 10), (11, 100)]

    k_counts = bins_hist(kd, kbins)
    l_counts = bins_hist(ld, lbins)

    # 3 examples per bin (keyboard) - use first pair per candidate for binning
    by_kbin: dict[tuple[int, int], list[tuple[str, str, int, int]]] = {
        b: [] for b in kbins
    }
    for typo, corr, k, lev in pairs_list:
        for lo, hi in kbins:
            if lo <= k <= hi:
                by_kbin[(lo, hi)].append((typo, corr, k, lev))
                break
    # 3 examples per bin (lev)
    by_lbin: dict[tuple[int, int], list[tuple[str, str, int, int]]] = {
        b: [] for b in lbins
    }
    for typo, corr, k, lev in pairs_list:
        for lo, hi in lbins:
            if lo <= lev <= hi:
                by_lbin[(lo, hi)].append((typo, corr, k, lev))
                break

    # Anomalies: keyboard much larger than levenshtein (possible non-typos)
    anomalies = []
    for typo, corr, k, lev in pairs_list:
        if k >= 2 * lev and lev >= 2:
            anomalies.append((typo, corr, k, lev, "keyboard >> lev"))
        elif lev >= 2 * k and k >= 2:
            anomalies.append((typo, corr, k, lev, "lev >> keyboard"))

    # Ensure unified output when writing
    if "rule_id" not in data:
        data["rule_id"] = "transcription_typos"
    if "rule_name" not in data:
        data["rule_name"] = "Transcription typos (Rule 0)"
    for c in candidates:
        if "span" not in c and "typo" in c:
            c["span"] = c["typo"]
        for occ in c.get("occurrences", []):
            if "start_index" not in occ:
                occ["start_index"] = 0
    # Write back
    out_path.parent.mkdir(parents=True, exist_ok=True)
    with out_path.open("w") as f:
        json.dump(data, f, indent=2)

    # Report
    print("=== Keyboard distance ===\n")
    print(f"  Min: {min(kd)}, Max: {max(kd)}, Mean: {sum(kd) / n:.2f}")
    print("  Bins:")
    for (lo, hi), cnt in zip(kbins, k_counts, strict=False):
        print(f"    {lo}-{hi}: {cnt}")
    print("  Examples per bin (keyboard):")
    for lo, hi in kbins:
        arr = by_kbin[(lo, hi)][:3]
        for typo, corr, k, _ in arr:
            print(f'    {lo}-{hi}: "{typo}" -> "{corr}" (k={k})')
    print("\n=== Levenshtein distance ===\n")
    print(f"  Min: {min(ld)}, Max: {max(ld)}, Mean: {sum(ld) / n:.2f}")
    print("  Bins:")
    for (lo, hi), cnt in zip(lbins, l_counts, strict=False):
        print(f"    {lo}-{hi}: {cnt}")
    print("  Examples per bin (lev):")
    for lo, hi in lbins:
        arr = by_lbin[(lo, hi)][:3]
        for typo, corr, _, lev in arr:
            print(f'    {lo}-{hi}: "{typo}" -> "{corr}" (lev={lev})')

    print("\n=== Anomalies (keyboard vs lev disparity) ===\n")
    for typo, corr, k, lev, tag in anomalies[:20]:
        print(f'  {tag}: "{typo}" -> "{corr}" (keyboard={k}, lev={lev})')
    if len(anomalies) > 20:
        print(f"  ... and {len(anomalies) - 20} more")

    print(f"\nDistances written to {out_path}")
    sys.exit(0)


if __name__ == "__main__":
    main()
